import numpy as np,torch
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from models.distribution_alignment import finalize_moments
from models.dual_branch_cache import sha256_file
from scripts.p8_5_distribution_bias_diagnosis import dist_metrics,mmd

O=Path('dual_branch_outputs/p8_5_distribution_bias');P7=Path('dual_branch_outputs/p7_downstream');P8=Path('dual_branch_outputs/p8_diagnosis');load=lambda p:json.loads(Path(p).read_text())
def stats(path,device='cuda:0'):
 x=np.load(path,mmap_mode='r');count=0;total=np.zeros(1024);cross=np.zeros((1024,1024))
 for start in range(0,len(x),8):
  t=torch.from_numpy(np.array(x[start:start+8],dtype=np.float32,copy=True)).to(device).reshape(-1,1024);total+=t.double().sum(0).cpu().numpy();cross+=(t.T@t).double().cpu().numpy();count+=len(t)
 mean,std,cov=finalize_moments(count,total,cross);return {'mean':mean,'std':std,'cov':cov}
def main():
 train=load(O/'distribution_metrics.json');source={k:v for k,v in np.load(O/'train_stats_full_real.npz').items()};target={k:v for k,v in np.load(O/'train_stats_clip.npz').items()};analytic=np.load(O/'analytic_transforms.npz');scale=analytic['full_real_affine_scale'];wct=analytic['full_real_wct_matrix'];affine_cov=source['cov']*np.outer(scale,scale);wct_cov=wct.T@source['cov']@wct
 train['train_correction_expected']={'mean':dist_metrics({'mean':target['mean'],'std':source['std'],'cov':source['cov']},target),'affine':dist_metrics({'mean':target['mean'],'std':np.sqrt(np.maximum(np.diag(affine_cov),0)),'cov':affine_cov},target),'wct':dist_metrics({'mean':target['mean'],'std':np.sqrt(np.maximum(np.diag(wct_cov),0)),'cov':wct_cov},target)}
 spectra=np.load(O/'train_distribution_stats.npz');clip_spectrum=np.maximum(spectra['clip_eigenvalues'],0);clip_spectrum/=clip_spectrum.sum()
 for row in train['pca_summary']:
  values=np.maximum(spectra[f"{row['source']}_eigenvalues"],0);values/=values.sum();row['spectrum_l1_distance_to_clip']=float(np.abs(values-clip_spectrum).sum());row['spectrum_l2_distance_to_clip']=float(np.linalg.norm(values-clip_spectrum))
 test_stats={'clip':stats(O/'test_clip_patch_fp16.npy'),'full_real_raw':stats(P7/'full_real_z_out_fp16.npy')}
 for kind in ('mean','affine','wct'):test_stats[kind]=stats(O/f'full_real_{kind}_test_fp16.npy')
 train['test_application']={k:dist_metrics(v,test_stats['clip']) for k,v in test_stats.items() if k!='clip'}
 ids=np.sort(np.random.default_rng(85242).choice(982,32,replace=False));clip_tokens=np.asarray(np.load(O/'test_clip_patch_fp16.npy',mmap_mode='r')[ids],dtype=np.float32).reshape(-1,1024)
 paths={'full_real_raw':P7/'full_real_z_out_fp16.npy',**{k:O/f'full_real_{k}_test_fp16.npy' for k in ('mean','affine','wct')}}
 for k,p in paths.items():train['test_application'][k]['mmd']=mmd(np.asarray(np.load(p,mmap_mode='r')[ids],dtype=np.float32).reshape(-1,1024),clip_tokens,'cuda:0')
 (O/'distribution_metrics.json').write_text(json.dumps(train,indent=2)+'\n')
 rep=load(O/'representation_metrics.json');hard_p8=load(P8/'p8_hard_retrieval.json')['models'];hard={'umbrae_raw':hard_p8['umbrae'],'full_real_raw':hard_p8['full_real'],**{f'full_real_{k}':rep[k]['hard_retrieval'] for k in rep}};(O/'hard_retrieval.json').write_text(json.dumps(hard,indent=2)+'\n')
 cap=load(O/'caption_metrics.json');ground=load(O/'grounding_metrics.json');p7=load(P7/'p7_raw_metrics.json');p8=load(P8/'p8_summary.json');rawrep=load(P8/'p8_projector_diagnostics.json')['modes'];rows={
  'umbrae_raw':{'RSA':rawrep['umbrae']['rsa_before_projector']['spearman_rsa'],'CIDEr':p7['caption_metrics']['umbrae']['CIDEr'],'BLEU-4':p7['caption_metrics']['umbrae']['BLEU-4'],'ROUGE-L':p7['caption_metrics']['umbrae']['ROUGE-L'],'Mean_IoU':p7['grounding_metrics']['umbrae']['mean_iou'],'Grounding_Accuracy':p7['grounding_metrics']['umbrae']['grounding_accuracy']},
  'full_real_raw':{'RSA':rawrep['full_real']['rsa_before_projector']['spearman_rsa'],'CIDEr':p7['caption_metrics']['full_real']['CIDEr'],'BLEU-4':p7['caption_metrics']['full_real']['BLEU-4'],'ROUGE-L':p7['caption_metrics']['full_real']['ROUGE-L'],'Mean_IoU':p7['grounding_metrics']['full_real']['mean_iou'],'Grounding_Accuracy':p7['grounding_metrics']['full_real']['grounding_accuracy']},
  'full_real_alpha_0_25':{k:p8['sweet_spot'][k] for k in ('RSA','CIDEr','BLEU-4','ROUGE-L','Mean_IoU','Grounding_Accuracy')}}
 for k in ('mean','affine','wct'):rows[f'full_real_{k}']={'RSA':rep[k]['rsa']['spearman_rsa'],'CIDEr':cap[k]['CIDEr'],'BLEU-4':cap[k]['BLEU-4'],'ROUGE-L':cap[k]['ROUGE-L'],'Mean_IoU':ground[k]['mean_iou'],'Grounding_Accuracy':ground[k]['grounding_accuracy'],'parse_failures':ground[k]['parse_failures'],'Hard_R1':rep[k]['hard_retrieval']['recall_at_1'],'Hard_MRR':rep[k]['hard_retrieval']['mrr'],'Projected_RSA':rep[k]['projector_rsa']['spearman_rsa']}
 meta=load(O/'transformation_metadata.json');meta['provenance']={'brainx_sha256':sha256_file('train_logs/brainx-v-1-4/last.pth'),'p6_full_real_sha256':sha256_file('dual_branch_outputs/dualbranch_s1_stageC_real_lora_r8_seed42_protocolv1/best.pth'),'mm_projector_sha256':sha256_file('model_weights/mm_projector.bin'),'CLIP_model':'openai/clip-vit-large-patch14','CLIP_feature':'hidden_states[-2][:,1:,:]','Shikra_identifier':str(Path('model_weights/shikra-7b').resolve()),'train_samples':8559,'train_tokens':2191104,'test_samples':982,'TEST_STATUS':'POST_HOC_REUSED_TEST','dual_gpu_execution':{'gpus':['cuda:0 RTX A6000','cuda:1 RTX A6000'],'strategy':'static sample partition plus safe tail repartition','both_gpus_performed_generation':True}}
 (O/'transformation_metadata.json').write_text(json.dumps(meta,indent=2)+'\n')
 summary={'comparison':rows,'MEAN_BIAS_SIGNAL':'WEAK','CHANNEL_SCALE_BIAS_SIGNAL':'NEGATIVE','COVARIANCE_BIAS_SIGNAL':'NEGATIVE','DISTRIBUTION_BIAS_HYPOTHESIS':'NOT_SUPPORTED','OVER_CALIBRATION_HYPOTHESIS':'SUPPORTED','mechanism':'MAGNITUDE_CONTROL_DOMINANT','NEXT_STAGE':'P9_PRESERVATION_CONSTRAINED_STRENGTH_CONTROL','TEST_STATUS':'POST_HOC_REUSED_TEST','safety_checks':{'NO_TRAINABLE_PARAMETERS':True,'NO_OPTIMIZER':True,'NO_BACKWARD':True,'NO_TEST_DERIVED_TRANSFORM_STATISTICS':True,'NO_TEST_CLIP_LEAKAGE_IN_FITTING':True,'NO_CHECKPOINT_MODIFICATION':True,'PARCEL_STAGE_STARTED':False,'PRF_STAGE_STARTED':False,'RETINOTOPY_STAGE_STARTED':False},'P8_5_STATUS':'COMPLETE'};(O/'p8_5_summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 d=train['full_real'];pc=next(x for x in train['pca_summary'] if x['source']=='clip');pr=next(x for x in train['pca_summary'] if x['source']=='full_real');r=rows
 report=f'''# P8.5 Distribution Bias Diagnosis Report\n\n## 1. Setup\nTrain-only fit: 8,559 samples / 2,191,104 tokens. Test is post-hoc reused test. No training.\n\n## 2. Mean Shift\nFull Real–CLIP mean L2={d['mean_shift_l2']:.6f}, relative={d['relative_mean_shift']:.6f}, cosine={d['mean_cosine']:.6f}.\n\n## 3. Channel Scale\nFull Real mean std ratio={d['std_ratio_mean']:.6f}; std-channel correlation={d['std_channel_correlation']:.6f}. A large scale mismatch exists.\n\n## 4. Covariance / Correlation\nNormalized covariance distance={d['normalized_covariance_frobenius_distance']:.6f}; correlation Frobenius distance={d['correlation_matrix_frobenius_distance']:.6f}.\n\n## 5. PCA Geometry\nEffective rank: Full Real={pr['effective_rank']:.3f}, CLIP={pc['effective_rank']:.3f}. Full Real is far more anisotropic.\n\n## 6. Distribution Distance\nTrain MMD and train-fitted test-application distances are recorded in distribution_metrics.json. Analytic corrections repair marginal moments but do not imply semantic alignment.\n\n## 7. Analytic Corrections\nMean-only, channel affine, and WCT are fitted solely from train statistics. WCT epsilon=1e-4; Full Real source covariance clamps {meta['transforms']['full_real']['source_eigensystem']['clamped_dimension_count']} dimensions.\n\n## 8. Representation Results\nAffine/WCT improve hard retrieval, but WCT lowers RSA and projected RSA. See representation_metrics.json and hard_retrieval.json.\n\n## 9. Caption Results\n| Variant | CIDEr | BLEU-4 | ROUGE-L |\n|---|---:|---:|---:|\n| UMBRAE | {r['umbrae_raw']['CIDEr']:.6f} | {r['umbrae_raw']['BLEU-4']:.6f} | {r['umbrae_raw']['ROUGE-L']:.6f} |\n| Full raw | {r['full_real_raw']['CIDEr']:.6f} | {r['full_real_raw']['BLEU-4']:.6f} | {r['full_real_raw']['ROUGE-L']:.6f} |\n| alpha=.25 | {r['full_real_alpha_0_25']['CIDEr']:.6f} | {r['full_real_alpha_0_25']['BLEU-4']:.6f} | {r['full_real_alpha_0_25']['ROUGE-L']:.6f} |\n| Mean | {r['full_real_mean']['CIDEr']:.6f} | {r['full_real_mean']['BLEU-4']:.6f} | {r['full_real_mean']['ROUGE-L']:.6f} |\n| Affine | {r['full_real_affine']['CIDEr']:.6f} | {r['full_real_affine']['BLEU-4']:.6f} | {r['full_real_affine']['ROUGE-L']:.6f} |\n| WCT | {r['full_real_wct']['CIDEr']:.6f} | {r['full_real_wct']['BLEU-4']:.6f} | {r['full_real_wct']['ROUGE-L']:.6f} |\n\n## 10. Grounding Results\nMean correction is mixed and tiny. Affine/WCT strongly reduce IoU/accuracy and increase parse failures.\n\n## 11. Projector-Space Diagnostics\nCorrected projected norms/RSA/cosine are in representation_metrics.json. Statistical matching does not preserve the decoder interface.\n\n## 12. Mechanism Comparison\nAlpha=.25 clearly outperforms mean/affine/WCT downstream. The P8 sweet spot is primarily magnitude control, not marginal distribution-bias removal.\n\n## 13. Final Interpretation\nMEAN_BIAS_SIGNAL = WEAK\nCHANNEL_SCALE_BIAS_SIGNAL = NEGATIVE\nCOVARIANCE_BIAS_SIGNAL = NEGATIVE\nDISTRIBUTION_BIAS_HYPOTHESIS = NOT_SUPPORTED\nOVER_CALIBRATION_HYPOTHESIS = SUPPORTED\nNEXT_STAGE = P9_PRESERVATION_CONSTRAINED_STRENGTH_CONTROL\nP8_5_STATUS = COMPLETE\n''';(O/'p8_5_report.md').write_text(report);print(json.dumps(summary,indent=2))
